import fs from 'node:fs';
import path from 'node:path';

/** Generated by `pnpm docs:api` (TypeDoc) from the package sources. Never edit by hand. */
const API_ROOT = path.join(process.cwd(), 'content', 'api');
const SCOPE = '@astack-tech';

/** URL prefix of the API reference. */
export const API_BASE = '/docs/api';

/** Packages in the order the docs introduce them. */
export const API_PACKAGES = ['core', 'components', 'tools', 'integrations'] as const;

export type ApiPackage = (typeof API_PACKAGES)[number];

/** Section headings for the generated folders. */
const KIND_LABELS: Record<string, string> = {
  classes: 'Classes',
  functions: 'Functions',
  interfaces: 'Interfaces',
  'type-aliases': 'Type aliases',
  variables: 'Variables',
  namespaces: 'Namespaces',
};

export interface ApiPage {
  /** URL segments below `/docs/api`, for example `['core', 'classes', 'Pipeline']`. */
  segments: string[];
  /** Package the page belongs to. */
  pkg: ApiPackage;
  /** Page title without the TypeDoc kind prefix, for example `Pipeline`. */
  title: string;
  /** Kind label, for example `Class`, or `Package` for a package overview. */
  kind: string;
  /** First paragraph of the page, used as the description. */
  summary: string;
  /** Markdown body with the title removed and links rewritten to site URLs. */
  markdown: string;
}

function isApiPackage(value: string): value is ApiPackage {
  return (API_PACKAGES as readonly string[]).includes(value);
}

/** Converts a path of a generated file to URL segments. */
function fileToSegments(relativeFile: string): string[] {
  const withoutExt = relativeFile.replace(/\.md$/u, '');
  const parts = withoutExt.split('/').filter(part => part !== SCOPE);
  if (parts.at(-1) === 'README') {
    parts.pop();
  }
  return parts;
}

/** Converts URL segments back to the generated file path. */
function segmentsToFile(segments: readonly string[]): string {
  const direct = path.join(API_ROOT, SCOPE, `${segments.join('/')}.md`);
  return fs.existsSync(direct) ? direct : path.join(API_ROOT, SCOPE, ...segments, 'README.md');
}

function walk(dir: string): string[] {
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap(entry => {
    const full = path.join(dir, entry.name);
    return entry.isDirectory() ? walk(full) : [full];
  });
}

/**
 * Rewrites relative `.md` links in a generated file to site URLs, keeping anchors.
 */
function rewriteLinks(markdown: string, fileDir: string): string {
  return markdown.replace(/\]\(([^)\s]+?\.md)(#[^)\s]*)?\)/gu, (match, target: string, anchor) => {
    if (/^[a-z]+:\/\//u.test(target)) {
      return match;
    }
    const absolute = path.resolve(fileDir, target);
    const relative = path.relative(API_ROOT, absolute).split(path.sep).join('/');
    const segments = fileToSegments(relative);
    const url = segments.length === 0 ? API_BASE : `${API_BASE}/${segments.join('/')}`;
    return `](${url}${typeof anchor === 'string' ? anchor.toLowerCase() : ''})`;
  });
}

/** Returns every API page, package overviews first. */
export function getAllApiPages(): ApiPage[] {
  if (!fs.existsSync(path.join(API_ROOT, SCOPE))) {
    return [];
  }
  return walk(path.join(API_ROOT, SCOPE))
    .filter(file => file.endsWith('.md'))
    .map(file => fileToSegments(path.relative(API_ROOT, file).split(path.sep).join('/')))
    .map(segments => getApiPage(segments))
    .filter((page): page is ApiPage => page !== undefined)
    .sort((a, b) => a.segments.length - b.segments.length || a.title.localeCompare(b.title));
}

/** Reads one API page by its URL segments. */
export function getApiPage(segments: readonly string[]): ApiPage | undefined {
  const [pkg] = segments;
  if (pkg === undefined || !isApiPackage(pkg)) {
    return undefined;
  }
  const file = segmentsToFile(segments);
  if (!fs.existsSync(file)) {
    return undefined;
  }

  const source = fs.readFileSync(file, 'utf8');
  const heading = /^# (.+)$/mu.exec(source);
  const rawTitle = heading?.[1]?.trim() ?? segments.at(-1) ?? pkg;
  const kindMatch = /^(Class|Interface|Function|Type Alias|Variable|Namespace): (.+)$/u.exec(
    rawTitle
  );
  const title = kindMatch?.[2]?.replace(/\(\)$/u, '') ?? rawTitle;
  const kind = kindMatch?.[1] ?? 'Package';

  const body = heading ? source.slice(heading.index + heading[0].length) : source;
  const markdown = rewriteLinks(body.trim(), path.dirname(file));
  const summary =
    markdown
      .split(/\n{2,}/u)
      .find(block => block.trim() !== '' && !block.startsWith('Defined in:') && !/^[#`|-]/u.test(block))
      ?.replace(/\[([^\]]+)\]\([^)]+\)/gu, '$1')
      .replace(/\s+/gu, ' ')
      .trim() ?? '';

  return { segments: [...segments], pkg, title, kind, summary, markdown };
}

export interface ApiGroup {
  label: string;
  pages: ApiPage[];
}

/** Groups the member pages of a package by kind, in TypeDoc's folder order. */
export function getPackageGroups(pkg: ApiPackage): ApiGroup[] {
  const pages = getAllApiPages().filter(page => page.pkg === pkg && page.segments.length > 1);
  return Object.entries(KIND_LABELS)
    .map(([folder, label]) => ({
      label,
      // The folder right above a page decides its kind, so `namespaces/X/classes/Y` is a class.
      pages: pages.filter(page => page.segments.at(-2) === folder),
    }))
    .filter(group => group.pages.length > 0);
}

/** URL of an API page. */
export function apiHref(segments: readonly string[]): string {
  return segments.length === 0 ? API_BASE : `${API_BASE}/${segments.join('/')}`;
}
